function parseCommand(text) {
  const t = String(text || '').toLowerCase().trim();
  const C = {
    'start': 'start', 'старт': 'start', '/start': 'start',
    'help': 'help', 'помощь': 'help', '/help': 'help',
    'status': 'status', 'статус': 'status', '/status': 'status',
    'cancel': 'cancel', 'стоп': 'cancel', 'отмена': 'cancel', '/cancel': 'cancel',
    'ping': 'ping', 'пинг': 'ping', '/ping': 'ping',
    'start_cycle': 'start_cycle', 'запуск цикла': 'start_cycle', 'старт цикла': 'start_cycle', '/start_cycle': 'start_cycle',
    'mode': 'mode', 'режим': 'mode', '/mode': 'mode',
    'topics': 'topics', 'темы': 'topics', '/topics': 'topics',
    'competitors': 'competitors', 'конкуренты': 'competitors', '/competitors': 'competitors',
    'accounts': 'accounts', 'аккаунты': 'accounts', '/accounts': 'accounts',
    'budget': 'budget', 'бюджет': 'budget', '/budget': 'budget',
    'clients': 'clients', 'клиенты': 'clients', '/clients': 'clients',
    'client': 'client', 'клиент': 'client', '/client': 'client',
    'reload_skills': 'reload_skills', '/reload_skills': 'reload_skills',
    'creators': 'creators', 'авторы': 'creators', 'поиск авторов': 'creators', '/creators': 'creators',
    'creator': 'creator', 'автор': 'creator', '/creator': 'creator',
    'creator_content': 'creator_content', 'creator-content': 'creator_content', 'контент автора': 'creator_content', '/creator_content': 'creator_content', '/creator-content': 'creator_content',
    'audience': 'audience', 'аудитория': 'audience', '/audience': 'audience',
    'transcript': 'transcript', 'транскрипт': 'transcript', '/transcript': 'transcript',
    'comments': 'comments', 'комментарии': 'comments', '/comments': 'comments',
    'upload_avatar': 'upload_avatar', 'upload-avatar': 'upload_avatar', 'загрузить аватар': 'upload_avatar', '/upload_avatar': 'upload_avatar', '/upload-avatar': 'upload_avatar',
    'my_avatars': 'my_avatars', 'my-avatars': 'my_avatars', 'мои аватары': 'my_avatars', '/my_avatars': 'my_avatars', '/my-avatars': 'my_avatars',
    'asset': 'asset', 'ассет': 'asset', '/asset': 'asset',
    'shorts': 'shorts', 'шортсы': 'shorts', '/shorts': 'shorts',
    'product': 'product', 'продукт': 'product', '/product': 'product',
    'banner': 'banner', 'баннер': 'banner', '/banner': 'banner',
    'publish_type': 'publish_type', 'publish-type': 'publish_type', 'тип публикации': 'publish_type', '/publish_type': 'publish_type', '/publish-type': 'publish_type',
  };
  const words = t.split(/\s+/);
  let command = 'unknown';
  const args = { url: null, id: null, value: null, platform: null, handle: null };
  if (t.startsWith('onboard ') || t === 'onboard' || t.startsWith('/onboard')) { command = 'onboard'; args.url = words[1] || null; }
  else if (t.startsWith('онбординг ') || t === 'онбординг') { command = 'onboard'; args.url = words[1] || null; }
  else if (t.startsWith('client ') || t.startsWith('клиент ') || t.startsWith('/client ')) { command = 'client'; args.id = words[1] || null; }
  else if (t.startsWith('creator ') || t.startsWith('автор ') || t.startsWith('/creator ')) { command = 'creator'; args.platform = words[1] || null; args.handle = words[2] || null; }
  else if (t.startsWith('creator_content ') || t.startsWith('creator-content ') || t.startsWith('контент автора ') || t.startsWith('/creator_content ') || t.startsWith('/creator-content ')) { command = 'creator_content'; const off = t.startsWith('контент автора ') ? 2 : 1; args.platform = words[off] || null; args.handle = words[off + 1] || null; }
  else if (t.startsWith('audience ') || t.startsWith('аудитория ') || t.startsWith('/audience ')) { command = 'audience'; args.platform = words[1] || null; args.handle = words[2] || null; }
  else if (t.startsWith('поиск авторов ')) { command = 'creators'; args.value = words.slice(2).join(' ') || null; }
  else if (t.startsWith('загрузить аватар ')) { command = 'upload_avatar'; args.value = words.slice(2).join(' ') || null; }
  else if (t.startsWith('тип публикации ')) { command = 'publish_type'; args.value = words.slice(2).join(' ') || null; }
  else if (C[t]) { command = C[t]; }
  else if (C[words[0]]) { command = C[words[0]]; args.value = words.slice(1).join(' ') || null; }
  return { command: command, args: args };
}

let out = null;
if (item.callback_query) {
  const q = item.callback_query;
  const fromId = (q.from && q.from.id) || null;
  const chatId = (q.message && q.message.chat && q.message.chat.id) || null;
  const msgId = (q.message && q.message.message_id) || null;
  const data = String(q.data || '');
  if (data.startsWith('cmd:')) {
    const parsed = parseCommand(data.slice(4));
    out = { kind: 'message', tg_user_id: fromId, chat_id: chatId, message_id: msgId, query_id: String(q.id || ''),
            command: parsed.command, args: parsed.args, raw: data, callback_action: null, entity_type: null, entity_id: null };
  } else {
    const parts = data.split(':');
    const action = parts[0] || '';
    const entityType = parts[1] || null;
    const entityId = parts.slice(2).join(':') || null;
    const map = {
      approve: { topic: 'approve_topic', script: 'approve_script', gen: 'publish_gen' },
      edit: { topic: 'edit_topic', script: 'edit_script' },
      reject: { topic: 'reject_topic', script: 'reject_script', gen: 'reject_gen' },
      alt: { topic: 'alt_topic' },
      regen: { gen: 'regen_gen' },
      toggle: { platform: 'toggle_platform' },
      publish: { gen: 'publish_gen' },
      confirm: { publish: 'confirm_publish' },
    };
    let cb = 'unknown';
    if (action === 'schedule') cb = 'schedule';
    else if (action === 'confirm') cb = 'confirm_publish';
    else if (action === 'publish') cb = 'publish_gen';
    else if (map[action] && map[action][entityType]) cb = map[action][entityType];
    out = { kind: 'callback', tg_user_id: fromId, chat_id: chatId, message_id: msgId, query_id: String(q.id || ''),
            command: null, args: {}, raw: data, callback_action: cb, entity_type: entityType, entity_id: entityId };
  }
} else if (item.message) {
  const m = item.message;
  const fromId = (m.from && m.from.id) || null;
  const chatId = (m.chat && m.chat.id) || null;
  const text = String(m.text || '').trim();
  const parsed = parseCommand(text);
  out = { kind: 'message', tg_user_id: fromId, chat_id: chatId, message_id: m.message_id || null, query_id: null,
          command: parsed.command, args: parsed.args, raw: text, callback_action: null, entity_type: null, entity_id: null };
} else {
  out = { kind: 'unknown', tg_user_id: null, chat_id: null, message_id: null, query_id: null, command: 'unknown', args: {}, raw: '', callback_action: null, entity_type: null, entity_id: null };
}
return [{ json: out }];

